using System.Collections.Immutable;
using System.Diagnostics.CodeAnalysis;
using System.IO;
using System.Reflection;
using AwesomeAssertions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;

namespace QuickER.Tests.CodeGen.CSharp;

/// <summary>
/// ランタイムのパッケージ用ソースとコミット済みの全フィクスチャ（生成コード）へ、src と同じカルチャの規則
/// （CA1304・CA1309・CA1310・CA1311）を掛け、診断を理由つきの既知の一覧と厳密に照合する
/// </summary>
/// <remarks>
/// <para>
/// 生成コードのファイルは先頭に <c>// &lt;auto-generated /&gt;</c> を持つため、ビルドのアナライザは既定で飛ばす。
/// ここではアナライザの設定で <c>generated_code = false</c> を与えて解析する。アナライザの DLL は src のビルドが使うのと同じ SDK 同梱のもので、
/// 場所はテストの csproj が AssemblyMetadata（<c>QuickER.NetAnalyzers</c>）で渡す。
/// </para>
/// <para>
/// 既知の一覧に載せるのは、理由があってカルチャの比較のまま残すものだけ（いまは無い）。一覧に無い診断も、載っているのに出ない診断も赤にする。
/// </para>
/// <para>
/// これらの規則は式木の中の呼び出しを診断しない（式木の比較は SQL などへ翻訳されるので、多重定義を変えると翻訳できない）。
/// 簡易 DSL と手書きの LINQ の条件は式木なので、インメモリの実行器での比べ方は <see cref="InMemoryStringMatchOrdinalTests"/> が固定する。
/// </para>
/// </remarks>
public sealed class GeneratedCodeCultureAnalyzerTests(ITestOutputHelper output)
{
    private static CancellationToken Ct => TestContext.Current.CancellationToken;

    /// <summary>解析する規則</summary>
    private static readonly string[] Rules = ["CA1304", "CA1309", "CA1310", "CA1311"];

    private static readonly string[] RuntimePackageSources =
    [
        "src/QuickER.Runtime/Runtime.g.cs",
        "src/QuickER.Runtime.SqlServer/Runtime.SqlServer.g.cs",
        "src/QuickER.Runtime.Sqlite/Runtime.Sqlite.g.cs",
        "src/QuickER.Runtime.EntityFrameworkCore/Runtime.EntityFrameworkCore.g.cs",
        "src/QuickER.Runtime.InMemory/Runtime.InMemory.g.cs",
        "src/QuickER.Runtime.AspNetCore/Runtime.AspNetCore.g.cs",
        "src/QuickER.Runtime.Sync/Runtime.Sync.g.cs",
    ];

    /// <summary>既知の診断（ファイル・規則・件数・理由）</summary>
    private static readonly (string File, string Rule, int Count, string Reason)[] Known = [];

    [Fact(
        DisplayName = "生成コードのカルチャの診断は、理由つきの既知の一覧と一致する（ランタイムと全フィクスチャ）"
    )]
    public async Task CultureDiagnostics_MatchKnownList()
    {
        var analyzers = LoadAnalyzers();
        var actual = new SortedDictionary<(string File, string Rule), int>();

        foreach (var (name, compilation) in Compilations())
        {
            foreach (var diagnostic in await AnalyzeAsync(compilation, analyzers))
            {
                var key = (
                    Path.GetFileName(diagnostic.Location.SourceTree!.FilePath),
                    diagnostic.Id
                );
                actual[key] = actual.GetValueOrDefault(key) + 1;
                output.WriteLine($"{name}: {diagnostic}");
            }
        }

        var expected = Known.ToDictionary(k => (k.File, k.Rule), k => k.Count);
        actual.Should().BeEquivalentTo(expected);
    }

    [Fact(
        DisplayName = "自己検査: auto-generated の印のあるソースでも 4 つの規則がそれぞれ診断を出し、式木の中では出さない"
    )]
    public async Task Probe_EveryRuleFires_InAutoGeneratedSource()
    {
        const string probe = """
            // <auto-generated />
            using System;
            using System.Linq.Expressions;

            namespace Probe;

            public static class Calls
            {
                public static object[] Run(string text) =>
                [
                    text.ToUpper(),
                    string.Compare(text, "a", StringComparison.InvariantCulture),
                    text.StartsWith("a"),
                    text.ToLower(),
                ];

                // 式木の中の呼び出しは、どの規則も診断を出さない（翻訳される比較なので多重定義を変えられない）
                public static Expression<Func<string, bool>> Condition() => value => value.EndsWith("a");
            }
            """;
        var compilation = GeneratedCodeCompiler.CreateCompilation(
            [("Probe.g.cs", probe)],
            "Culture.Probe"
        );

        var diagnostics = (await AnalyzeAsync(compilation, LoadAnalyzers())).ToArray();

        diagnostics.Select(diagnostic => diagnostic.Id).Distinct().Should().BeEquivalentTo(Rules);
        diagnostics
            .Should()
            .NotContain(
                diagnostic => diagnostic.GetMessage(null).Contains("EndsWith"),
                "式木の中の EndsWith は診断されない（インメモリの式木の比較は InMemoryStringMatchOrdinalTests が固定する）"
            );
    }

    /// <summary>SDK 同梱のアナライザ DLL から、解析する規則を持つ C# のアナライザを読む</summary>
    private static ImmutableArray<DiagnosticAnalyzer> LoadAnalyzers()
    {
        var paths = typeof(GeneratedCodeCultureAnalyzerTests)
            .Assembly.GetCustomAttributes<AssemblyMetadataAttribute>()
            .Single(attribute => attribute.Key == "QuickER.NetAnalyzers")
            .Value!.Split(';', StringSplitOptions.RemoveEmptyEntries);
        paths.Should().HaveCount(2, "NetAnalyzers と CSharp.NetAnalyzers の 2 つ");

        var analyzers = new List<DiagnosticAnalyzer>();

        foreach (var path in paths)
        {
            Type?[] types;

            try
            {
                types = Assembly.LoadFrom(path).GetTypes();
            }
            catch (ReflectionTypeLoadException exception)
            {
                // コード修正（Workspaces を参照する型）は読めなくてよい。アナライザは読める
                types = exception.Types;
            }

            foreach (var type in types)
            {
                if (
                    type is null
                    || type.IsAbstract
                    || !typeof(DiagnosticAnalyzer).IsAssignableFrom(type)
                    || type.GetCustomAttribute<DiagnosticAnalyzerAttribute>() is not { } attribute
                    || !attribute.Languages.Contains(LanguageNames.CSharp)
                )
                {
                    continue;
                }

                var analyzer = (DiagnosticAnalyzer)Activator.CreateInstance(type)!;

                if (analyzer.SupportedDiagnostics.Any(descriptor => Rules.Contains(descriptor.Id)))
                {
                    analyzers.Add(analyzer);
                }
            }
        }

        analyzers.Should().NotBeEmpty();
        return [.. analyzers];
    }

    /// <summary>生成コードでないと宣言し、規則を警告として有効にしたうえで解析する</summary>
    private static async Task<IEnumerable<Diagnostic>> AnalyzeAsync(
        CSharpCompilation compilation,
        ImmutableArray<DiagnosticAnalyzer> analyzers
    )
    {
        var options = compilation.Options.WithSpecificDiagnosticOptions(
            Rules.ToDictionary(rule => rule, _ => ReportDiagnostic.Warn)
        );
        var diagnostics = await compilation
            .WithOptions(options)
            .WithAnalyzers(analyzers, new AnalyzerOptions([], new NotGeneratedConfigProvider()))
            .GetAnalyzerDiagnosticsAsync(Ct);
        return diagnostics.Where(diagnostic => Rules.Contains(diagnostic.Id));
    }

    private static IEnumerable<(string Name, CSharpCompilation Compilation)> Compilations()
    {
        var root = RepoRoot();
        var runtime = GeneratedCodeCompiler.CreateCompilation(
            RuntimePackageSources.Select(relative =>
                (Path.GetFileName(relative), File.ReadAllText(Path.Combine(root, relative)))
            ),
            "Culture.Runtime"
        );

        // ソースと同じ型を持つランタイムのパッケージ自身は参照から外す（同じ名前の型が 2 つになると束縛できない）
        yield return (
            "Runtime",
            runtime.RemoveReferences(
                runtime.References.Where(reference =>
                    Path.GetFileName(reference.Display ?? "")
                        .StartsWith("QuickER.Runtime", StringComparison.Ordinal)
                )
            )
        );

        foreach (
            var group in Directory
                .EnumerateFiles(
                    Path.Combine(root, "tests", "QuickER.Tests", "GeneratedFixture"),
                    "*.g.cs"
                )
                .GroupBy(path => Path.GetFileName(path).Split('.')[0])
                .OrderBy(group => group.Key, StringComparer.Ordinal)
        )
        {
            yield return (
                group.Key,
                GeneratedCodeCompiler.CreateCompilation(
                    group.Select(path => (Path.GetFileName(path), File.ReadAllText(path))),
                    "Culture." + group.Key
                )
            );
        }
    }

    private static string RepoRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);

        while (dir is not null)
        {
            if (File.Exists(Path.Combine(dir.FullName, "QuickER.slnx")))
            {
                return dir.FullName;
            }

            dir = dir.Parent;
        }

        throw new FileNotFoundException("リポジトリ直下（QuickER.slnx）が見つかりません。");
    }

    /// <summary>
    /// すべての構文木に <c>generated_code = false</c> を返す（.editorconfig の同じ設定と同じ働き）。
    /// アナライザの実行は、この設定が無いときだけ auto-generated の印とファイル名（<c>.g.cs</c>）で生成コードを判定して飛ばす
    /// </summary>
    private sealed class NotGeneratedConfigProvider : AnalyzerConfigOptionsProvider
    {
        private static readonly NotGeneratedOptions Options = new();

        public override AnalyzerConfigOptions GlobalOptions => Options;

        public override AnalyzerConfigOptions GetOptions(SyntaxTree tree) => Options;

        public override AnalyzerConfigOptions GetOptions(AdditionalText textFile) => Options;

        private sealed class NotGeneratedOptions : AnalyzerConfigOptions
        {
            public override bool TryGetValue(string key, [NotNullWhen(true)] out string? value)
            {
                value = key == "generated_code" ? "false" : null;
                return value is not null;
            }
        }
    }
}
